-- Reference schema: the blog domain, MySQL 8 dialect. The same tables, columns, keys and
-- constraint names as blog.sql (PostgreSQL), so that every suite runs unchanged:
--
-- - bigserial keys are bigint AUTO_INCREMENT;
-- - text columns that are indexed or have a default are varchar(255);
-- - the array column posts.tags is json (an array of strings);
-- - jsonb is json, timestamptz is datetime(6) (the adapter's session is UTC);
-- - uuid is char(36), generated by uuid() when no value is given;
-- - unique and foreign-key constraints carry Postgres's default names.
--
-- Load with loadFixture(db, "blog") from ../db.ts.

CREATE TABLE users (
  id            bigint AUTO_INCREMENT PRIMARY KEY,
  email         varchar(255) NOT NULL,
  name          text,
  age           integer,
  role          varchar(255) NOT NULL DEFAULT 'member',
  password_hash text,
  settings      json,
  lock_version  integer NOT NULL DEFAULT 1,
  created_at    datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at    datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT users_email_key UNIQUE (email)
);

-- has_one: users -> profiles
CREATE TABLE profiles (
  id         bigint AUTO_INCREMENT PRIMARY KEY,
  user_id    bigint NOT NULL,
  bio        text,
  avatar_url text,
  CONSTRAINT profiles_user_id_key UNIQUE (user_id),
  CONSTRAINT profiles_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

-- has_many / belongs_to: users -> posts
CREATE TABLE posts (
  id           bigint AUTO_INCREMENT PRIMARY KEY,
  author_id    bigint NOT NULL,
  title        text NOT NULL,
  body         text,
  published    boolean DEFAULT false,
  views        integer DEFAULT 0,
  tags         json,
  published_at datetime(6),
  created_at   datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at   datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT posts_author_id_fkey FOREIGN KEY (author_id) REFERENCES users (id),
  INDEX posts_author_id_index (author_id)
);

CREATE TABLE comments (
  id          bigint AUTO_INCREMENT PRIMARY KEY,
  post_id     bigint NOT NULL,
  author_id   bigint,
  body        text NOT NULL,
  created_at  datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT comments_post_id_fkey FOREIGN KEY (post_id) REFERENCES posts (id) ON DELETE CASCADE,
  CONSTRAINT comments_author_id_fkey FOREIGN KEY (author_id) REFERENCES users (id),
  INDEX comments_post_id_index (post_id),
  INDEX comments_author_id_index (author_id)
);

-- many_to_many: posts <-> tags through posts_tags
CREATE TABLE tags (
  id   bigint AUTO_INCREMENT PRIMARY KEY,
  name varchar(255),
  CONSTRAINT tags_name_key UNIQUE (name)
);

CREATE TABLE posts_tags (
  post_id bigint NOT NULL,
  tag_id  bigint NOT NULL,
  PRIMARY KEY (post_id, tag_id),
  CONSTRAINT posts_tags_post_id_fkey FOREIGN KEY (post_id) REFERENCES posts (id) ON DELETE CASCADE,
  CONSTRAINT posts_tags_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES tags (id) ON DELETE CASCADE
);

-- uuid primary key
CREATE TABLE orgs (
  id   char(36) PRIMARY KEY DEFAULT (uuid()),
  name text NOT NULL
);

-- composite primary key
CREATE TABLE memberships (
  org_id  char(36) NOT NULL,
  user_id bigint NOT NULL,
  role    varchar(255) NOT NULL DEFAULT 'member',
  PRIMARY KEY (org_id, user_id),
  CONSTRAINT memberships_org_id_fkey FOREIGN KEY (org_id) REFERENCES orgs (id) ON DELETE CASCADE,
  CONSTRAINT memberships_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);
